begin;

-- University Canada West (Vancouver, Canada): new university record.
--
-- Sources: ucanwest.ca throughout (program pages, tuition and fees page, awards and
-- scholarships page, English proficiency page, campuses page, dates and deadlines page).
-- The site was fully accessible, so every figure below comes from UCW's own pages.
--
-- Scope (confirmed with user): the 8 credential-bearing academic programs. The 9
-- micro-credentials (9 to 35 hour professional short courses, enrolled by email, no
-- published tuition) and the Global Short-Term Student Visiting Program (a cultural
-- exchange placement with no published credential or fees) are excluded.
--
-- Tuition: UCW prices per course, so tuition_fee_per_year holds the published 2026
-- international per-course rate and each description carries the full published program
-- total plus the 2027 rate. university tuition_fee_min/max are annual equivalents derived
-- from those totals (online bachelor CAD 9,730/yr up to hybrid MBA CAD 23,048/yr).
--
-- Left null deliberately (not published by UCW, not guessed): ranking, acceptance_rate,
-- graduate_employability. UCW publishes a 92 per cent MBA alumni employment rate, but that
-- is MBA-specific rather than institution-wide, so it sits in the overview text instead of
-- the metric field. duration_years is null for the University Access Program because it
-- runs three months and a fractional year renders badly in the programs UI.
--
-- Scholarships: only the 5 awards open to international students are included. UCW's other
-- 8 awards (Canada 150 Armed Forces, Scholarships for Academic Excellence, Access to
-- Education, Gino Odjick, Lytton, Nurturing Wisdom, Emily Baker, Vancouver Canucks Alumni)
-- are restricted to domestic, Canadian-resident or Canadian Indigenous applicants.
--
-- is_published is FALSE: no logo or cover image yet. Upload both from the admin dashboard,
-- then set is_published = true.

insert into public.universities (id, name, slug, short_description, overview, city, founded_year, ranking, total_students, number_of_campuses, acceptance_rate, graduate_employability, international_students, intake_months, tuition_fee_min, tuition_fee_max, tuition_currency, has_on_campus, has_online, has_hybrid, is_featured, is_published, country_id, created_at, updated_at)
values (gen_random_uuid(), 'University Canada West', 'university-canada-west', 'University Canada West is a private, business and technology focused university in downtown Vancouver offering ACBSP-accredited Bachelor of Commerce, Business Communication and MBA degrees in hybrid and fully online formats, with four intakes a year and a student body drawn from more than 100 countries.', 'University Canada West (UCW) is a private, for-profit university established in 2004 in downtown Vancouver, British Columbia, and part of Global University Systems since 2014. It operates two campuses, the Vancouver House campus on Granville Street with more than 90,000 square feet across two podium buildings, and the West Pender campus in the London Building, a heritage tower in the city''s financial district close to Waterfront SkyTrain Station.

UCW is deliberately narrow in focus, concentrating on business, commerce, business communication and management rather than a broad faculty structure. Its Bachelor of Commerce and MBA are accredited by the Accreditation Council for Business Schools and Programs (ACBSP) and carry the NCMA designation from CIM Chartered Managers Canada, and the university holds Education Quality Assurance (EQA) designation from the British Columbia Ministry of Post-Secondary Education and Future Skills. The university reports more than 7,000 students from over 100 countries, and a 92 per cent employment rate among MBA alumni based on a December 2025 survey.

Programs run on four intakes a year in January, April, July and October, and most degrees are offered in two formats: a hybrid mode combining weekly on-campus classes with guided online learning, and a fully online asynchronous mode priced considerably lower. The distinction matters for international students, because UCW states that graduates of its online programs are not eligible for a Post-Graduation Work Permit under Immigration, Refugees and Citizenship Canada criteria, while hybrid students may qualify. Students who need to strengthen their academic English first can enter through the three-month University Access Program.', 'Vancouver, BC', 2004, null, 7000, 2, null, null, 96, 'January, April, July, October', 9730, 23048, 'CAD', true, true, true, false, false, (select id from public.countries where slug = 'canada'), now(), now());

-- 8 academic programs.
insert into public.programs (id, university_id, name, slug, degree_level, field, campus, application_fee,
  tuition_fee_per_year, duration_years, intake_months, entry_requirements, learn_more_url, description,
  created_at, updated_at)
select gen_random_uuid(), uni.id, v.name, v.slug, v.degree_level::"DegreeType", v.field, v.campus,
  'CAD 150', v.tuition, v.duration, 'January, April, July, October', v.entry_requirements, v.learn_more_url,
  v.description, now(), now()
from (select id from public.universities where slug = 'university-canada-west') as uni,
(values
  ('Bachelor of Commerce', 'bachelor-of-commerce-ucw', 'BACHELOR', 'Business', 'Vancouver, BC', 'CAD 2,225/course', 4, 'Canadian Grade 12 diploma or equivalent with an overall average of C or better (2.0 on a 4.33 scale). English proficiency: Academic IELTS 6.5 overall with a minimum 6.0 in writing, or equivalent (CAEL 70 with 60 writing, PTE Academic 61 with 60 writing, TOEFL iBT 88 with 20 writing, or Duolingo 110 with 100 writing). Applicants who do not meet the English requirement can enter through the University Access Program (UAC 030).', 'https://www.ucanwest.ca/programs/undergraduate/bachelor-of-commerce', 'UCW''s flagship undergraduate degree, a 120-credit program delivered over four years and 14 terms in hybrid mode, combining 2.5 hours on campus with 1.5 hours of guided online learning each week during weeks 1 to 10 of every 12-week term. Students can graduate with the general BCom or take one of three specialisations introduced from Winter 2026: Accounting, Marketing, or Technology Management. The degree is accredited by the Accreditation Council for Business Schools and Programs (ACBSP) and carries the NCMA designation from CIM Chartered Managers Canada, and an articulation agreement with CPA British Columbia lets graduates enter the CPA Professional Education Program having bypassed up to 15 prerequisite courses. International tuition is priced per course, with a published total of CAD 89,000 for the 40 courses in 2026, rising to CAD 93,440 in 2027.'),
  ('Online Bachelor of Commerce', 'online-bachelor-of-commerce-ucw', 'BACHELOR', 'Business', 'Online', 'CAD 973/course', 4, 'Canadian Grade 12 diploma or equivalent with an overall average of C or better (2.0 on a 4.33 scale). English proficiency: Academic IELTS 6.5 overall with a minimum 6.0 in writing, or equivalent (CAEL 70 with 60 writing, PTE Academic 61 with 60 writing, TOEFL iBT 88 with 20 writing, or Duolingo 110 with 100 writing). Applicants who do not meet the English requirement can enter through the University Access Program (UAC 030).', 'https://www.ucanwest.ca/programs/undergraduate/online-bachelor-of-commerce', 'The fully online version of UCW''s Bachelor of Commerce, covering the same 120 credits over four years with content delivered asynchronously through recorded lectures, readings and videos, so students study on their own schedule from anywhere. Tuition is substantially lower than the hybrid route, with a published total of CAD 38,920 for 40 courses in 2026 and the same rate for domestic and international students. Important for international applicants: UCW states that students graduating from its online programs are not eligible for a Post-Graduation Work Permit, because of the eligibility criteria set by Immigration, Refugees and Citizenship Canada.'),
  ('Bachelor of Arts in Business Communication', 'bachelor-of-arts-business-communication-ucw', 'BACHELOR', 'Business Communication', 'Vancouver, BC', 'CAD 2,225/course', 4, 'Canadian Grade 12 diploma or equivalent with an overall average of C or better (2.0 on a 4.33 scale). English proficiency: Academic IELTS 6.5 overall with a minimum 6.0 in writing, or equivalent (CAEL 70 with 60 writing, PTE Academic 61 with 60 writing, TOEFL iBT 88 with 20 writing, or Duolingo 110 with 100 writing). Applicants who do not meet the English requirement can enter through the University Access Program (UAC 030).', 'https://www.ucanwest.ca/programs/undergraduate/bachelor-of-arts-in-business-communication', 'A four-year, roughly 120-credit degree spanning 14 terms that pairs communication theory with applied business practice, taught in hybrid mode with 2.5 hours on campus and 1.5 hours of guided online learning each week during weeks 1 to 10 of each 12-week term. Graduates move into public relations, corporate communications, digital marketing, journalism, media planning, content creation, social media management and internal communications. The program is offered under the written consent of the Minister effective 22 July 2024, following a quality assessment process. International tuition is priced per course, with a published total of CAD 89,000 for 40 courses in 2026, rising to CAD 93,440 in 2027.'),
  ('Online Bachelor of Arts in Business Communication', 'online-bachelor-of-arts-business-communication-ucw', 'BACHELOR', 'Business Communication', 'Online', 'CAD 973/course', 4, 'Canadian Grade 12 diploma or equivalent with an overall average of C or better (2.0 on a 4.33 scale). English proficiency: Academic IELTS 6.5 overall with a minimum 6.0 in writing, or equivalent (CAEL 70 with 60 writing, PTE Academic 61 with 60 writing, TOEFL iBT 88 with 20 writing, or Duolingo 110 with 100 writing). Applicants who do not meet the English requirement can enter through the University Access Program (UAC 030).', 'https://www.ucanwest.ca/programs/undergraduate/online-bachelor-of-arts-in-business-communication', 'The fully online route to UCW''s Bachelor of Arts in Business Communication, delivered asynchronously over four years so students can study from anywhere at their own pace. Tuition is charged per course at the same rate for domestic and international students, with a published total of CAD 38,920 for 40 courses in 2026. Note that UCW states graduates of its online programs are not eligible for a Post-Graduation Work Permit under Immigration, Refugees and Citizenship Canada criteria, so this route suits students studying from their home country rather than those planning to work in Canada after graduation.'),
  ('Associate of Arts', 'associate-of-arts-ucw', 'ASSOCIATE', 'Arts and Sciences', 'Vancouver, BC', 'CAD 2,225/course', 2, 'Canadian Grade 12 diploma or equivalent with an overall average of C or better (2.0 on a 4.33 scale). English proficiency: Academic IELTS 6.5 overall with a minimum 6.0 in writing, or equivalent (CAEL 70 with 60 writing, PTE Academic 61 with 60 writing, TOEFL iBT 88 with 20 writing, or Duolingo 110 with 100 writing). Applicants who do not meet the English requirement can enter through the University Access Program (UAC 030).', 'https://www.ucanwest.ca/programs/undergraduate/associate-of-arts', 'A 60-credit, 20-course qualification completed over two years of full-time hybrid study, giving students a broad arts and sciences foundation alongside the option to enter the workforce or continue into a bachelor''s degree. After 30 credits students can transfer seamlessly into UCW''s Bachelor of Arts in Business Communication or Bachelor of Commerce, and the credential is accepted for transfer into bachelor programs at all British Columbia degree-granting institutions. UCW reports that 94 per cent of its Associate of Arts students were working in a paid job after graduation, based on a Spring 2023 survey. International tuition is priced per course, with a published total of CAD 44,500 for the 20 courses in 2026, rising to CAD 46,720 in 2027.'),
  ('Master of Business Administration (MBA)', 'master-of-business-administration-ucw', 'MASTER', 'Business', 'Vancouver, BC', 'CAD 3,073/course', 2, 'A bachelor''s degree from a recognised university with a cumulative GPA of 3.00 or better on a 4.33 scale, plus one of: a GMAT or GRE score taken within five years; a relevant professional designation (CPA, CA, CGA, CMA, CHRP or P.Eng); a bachelor''s degree in a business or STEM related field; or a minimum of three years of documented professional or management experience showing career progression. English proficiency: Academic IELTS 6.5 overall with a minimum 6.0 in writing, or equivalent (PTE Academic 61, TOEFL iBT 88, or Duolingo 115 with 105 writing), with results valid for two years. The requirement is waived for applicants who graduated from an English-language university. Since 25 February 2025 UCW no longer admits MBA students through the University Access Program, so applicants must meet direct-entry requirements.', 'https://www.ucanwest.ca/programs/graduate/master-of-business-administration', 'UCW''s MBA is a 36-credit graduate degree delivered across five terms over two years in hybrid mode, with 2.5 hours on campus and 1.5 hours of guided online learning each week during weeks 1 to 10 of each 12-week term. Students progress through the first two terms as a cohort before choosing one specialisation from Supply Chain Management, Entrepreneurship, Business Analytics, or Artificial Intelligence and Machine Learning Leadership. The program is accredited by ACBSP and carries the NCMA designation, and UCW reports a 93 per cent employment rate within one year of graduation. Unlike the online MBA, this hybrid route is eligible for the Post-Graduation Work Permit. Tuition is priced per course, with a published international total of CAD 46,095 based on 15 courses in 2026, rising to CAD 48,390 in 2027.'),
  ('Online Master of Business Administration (MBA)', 'online-mba-ucw', 'MASTER', 'Business', 'Online', 'CAD 1,494/course', 2, 'A bachelor''s degree from a recognised university with a cumulative GPA of 3.00 or better on a 4.33 scale, plus one of: a GMAT or GRE score taken within five years; a relevant professional designation (CPA, CA, CGA, CMA, CHRP or P.Eng); a bachelor''s degree in a business or STEM related field; or a minimum of three years of documented professional or management experience showing career progression. English proficiency: Academic IELTS 6.5 overall with a minimum 6.0 in writing, or equivalent (PTE Academic 61, TOEFL iBT 88, or Duolingo 115 with 105 writing), with results valid for two years. The requirement is waived for applicants who graduated from an English-language university. Since 25 February 2025 UCW no longer admits MBA students through the University Access Program, so applicants must meet direct-entry requirements.', 'https://www.ucanwest.ca/programs/graduate/online-mba', 'The fully online, asynchronous version of UCW''s MBA, carrying the same ACBSP-accredited and NCMA-designated curriculum as the hybrid program but studied entirely remotely at the student''s own pace. Tuition is charged at the same rate for domestic and international students, with a published total of CAD 22,410 for 15 courses in 2026, less than half the hybrid international price. The trade-off matters for anyone planning to stay in Canada: UCW states that international students completing the online asynchronous format are not eligible for a Post-Graduation Work Permit, whereas hybrid students may qualify.'),
  ('University Access Program (UAC 030)', 'university-access-program-ucw', 'FOUNDATION', 'English Language Preparation', 'Vancouver, BC', 'CAD 6,317 total', null, 'Academic IELTS 6.0 overall with a minimum 5.5 in writing, PTE 59, TOEFL iBT 80, TOEFL PBT 550, Duolingo 110, or Cambridge B2 First, C1 Advanced or C2 Proficiency. UCW accepts the IELTS One Skill Retake for individual components. Applicants must also meet the academic entry requirements for the undergraduate program they intend to progress into.', 'https://www.ucanwest.ca/programs/preparatory/university-access-program', 'A three-month, on-campus academic English program for students who meet UCW''s academic entry requirements but not its direct-entry English standard. UAC 030 is the advanced level and focuses on the academic English needed to study, complete assignments and sit examinations with confidence; students at this level may also take one quantitative academic course at the same time. Successful completion satisfies the English proficiency requirement for entry to UCW''s undergraduate degrees. Since 25 February 2025 the program no longer feeds into the MBA, which requires direct admission. The published international cost is CAD 6,317 for 2026, rising to CAD 6,633 in 2027.')
) as v(name, slug, degree_level, field, campus, tuition, duration, entry_requirements, learn_more_url,
  description);

-- Scholarships open to international students.
insert into public.scholarships (id, university_id, name, type, description, value, learn_more_url,
  created_at, updated_at)
select gen_random_uuid(), uni.id, v.name, v.type::"ScholarshipType", v.description, v.value,
  'https://www.ucanwest.ca/admissions/awards-scholarships', now(), now()
from (select id from public.universities where slug = 'university-canada-west') as uni,
(values
  ('Rising Scholars Grant', 'PARTIAL', 'An automatic entrance grant for international applicants to the Bachelor of Commerce or Bachelor of Arts in Business Communication who are from one of 31 specified countries, or who have been in Canada for at least one year. No separate application is required.', 'CAD 14,000'),
  ('Community Impact Grant', 'PARTIAL', 'Available to new students starting in the Fall 2026 or Winter 2027 terms on the Bachelor of Commerce, Bachelor of Arts in Business Communication or MBA, in return for volunteering 10 hours per term. It can be combined with the Regional Grant or Rising Scholars Grant. Requires an application.', 'CAD 3,000 (MBA) or CAD 14,000 (bachelor)'),
  ('Regional Grant', 'PARTIAL', 'An automatic entrance grant for international MBA applicants from one of 31 specified countries, or international students who have already been in Canada for at least one year. No separate application is required.', 'CAD 8,000'),
  ('MBA Excellence Scholarship for Continuing Students', 'MERIT_BASED', 'Open to both domestic and international MBA students who have completed at least 27 MBA credits with a minimum cumulative GPA of 3.80.', 'CAD 5,000'),
  ('University Canada West Alumni Grant', 'PARTIAL', 'For UCW graduates of a degree program from July 2017 onwards who are admitted to a new bachelor or master program at the university, covering the Bachelor of Commerce, Bachelor of Arts in Business Communication and MBA.', 'CAD 2,000')
) as v(name, type, description, value);

-- Admission steps.
insert into public.admission_steps (id, university_id, step_number, title, description, created_at, updated_at)
select gen_random_uuid(), uni.id, v.step_number, v.title, v.description, now(), now()
from (select id from public.universities where slug = 'university-canada-west') as uni,
(values
  (1, 'Apply Online and Pay the Application Fee', 'Submit an application through the UCW website for one of the four annual intakes in January, April, July or October. There is a non-refundable application fee of CAD 150, which is deducted from your tuition deposit once you start. International application deadlines fall roughly three to four weeks ahead of the domestic deadline for each term.'),
  (2, 'Submit Transcripts and Proof of English', 'Provide academic transcripts for credential assessment, plus proof of English proficiency. UCW accepts Academic IELTS, CAEL, PTE Academic, TOEFL iBT, Duolingo and Cambridge English, and the requirement is waived for applicants who completed a degree taught in English. MBA applicants also submit evidence of a GMAT or GRE score, a professional designation, a business or STEM degree, or three years of professional experience.'),
  (3, 'Accept Your Offer and Pay the Tuition Deposit', 'On receiving an offer, accept it and pay the tuition deposit to have your Letter of Acceptance issued. For international students the deposit is CAD 8,800 for hybrid programs and CAD 3,000 for online programs.'),
  (4, 'Apply for Your Study Permit', 'Use your Letter of Acceptance to apply to Immigration, Refugees and Citizenship Canada for a study permit. British Columbia applicants normally also need a Provincial Attestation Letter, which UCW issues to eligible students. Apply as early as possible, as processing times vary by country.')
) as v(step_number, title, description);

commit;
